function setView(name){$$('.view').forEach(v=>v.classList.remove('active'));$('#'+name+'View').classList.add('active');$$('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.view===name));window.scrollTo({top:0,behavior:'smooth'});if(name==='notes')renderSubjects();if(name==='qa')renderQA();}
function renderSubjects(filter=''){
 const grid=$('#subjectGrid');const filtered=subjects.filter(s=>(s.name+' '+s.si+' '+s.desc+' '+s.topics.map(t=>t.name).join(' ')).toLowerCase().includes(filter.toLowerCase()));$('#notesCount').textContent=`විෂයයන් ${filtered.length}ක්`;
 grid.innerHTML=filtered.map(s=>`<button class="subject-card" data-subject="${s.id}"><span class="subject-symbol">${s.icon}</span><strong>${s.name}</strong><p>${s.desc}</p><span class="card-bottom">${s.topics.length?`පාඩම් ${s.topics.length}ක්`:'සූදානම් වෙමින් පවතී'} &nbsp; ↗</span></button>`).join('')||'<div class="empty-state">ගැළපෙන විෂයයක් හමු නොවීය. වෙනත් වචනයක් සොයන්න.</div>';
 $$('#subjectGrid [data-subject]').forEach(b=>b.addEventListener('click',()=>openSubject(b.dataset.subject)));
}
function openSubject(id){currentSubject=id;const s=subjects.find(x=>x.id===id);$('#subjectGrid').classList.add('hidden');$('#topicPanel').classList.remove('hidden');$('#topicSubjectLabel').textContent=s.name.toUpperCase();$('#topicSubjectTitle').textContent=s.name;$('#topicSubjectDescription').textContent=s.desc;$('#topicGrid').innerHTML=s.topics.length?s.topics.map((t,i)=>`<button class="topic-card" data-topic="${t.id}"><span class="topic-number">පාඩම ${String(i+1).padStart(2,'0')}</span><strong>${t.name}</strong><p>${t.desc}</p><span class="card-bottom">පාඩම විවෘත කරන්න →</span></button>`).join(''):'<div class="empty-state">Notes for this subject are being prepared. Algebra lessons are available now.</div>';
 $$('#topicGrid [data-topic]').forEach(b=>b.addEventListener('click',()=>openLesson(id,b.dataset.topic)));
}
function openLesson(subjectId,topicId){const s=subjects.find(x=>x.id===subjectId),t=s.topics.find(x=>x.id===topicId);currentSubject=subjectId;currentTopic=t;currentSlides=t.slides;slideIndex=0;$('#lessonBreadcrumb').textContent=`පාඩම් සටහන් / ${s.name} / ${t.name}`;$('#lessonEyebrow').textContent=`${s.name} · ${t.name}`;$('#lessonTitle').textContent=t.name;$('#lessonSubtitle').textContent=t.desc;setView('lesson');renderSlide();}
function renderSlide(){const total=currentSlides.length,sl=currentSlides[slideIndex];$('#slideSection').textContent=({INTRODUCTION:'හැඳින්වීම',VARIABLES:'විචල්‍ය',CONSTANTS:'නියත පද',COEFFICIENTS:'සංගුණක','ALGEBRAIC EXPRESSIONS':'වීජීය ප්‍රකාශන','LIKE TERMS':'සමාන හා අසමාන පද',SIMPLIFICATION:'සරල කිරීම','MORE SIMPLIFICATION':'තවත් සරල කිරීම',MULTIPLICATION:'ගුණ කිරීම',DIVISION:'බෙදීම','CHECK YOUR UNDERSTANDING':'ඔබේ දැනුම පරීක්ෂා කරමු','BALANCE RULE':'සමතුලිතතා නියමය','ADDITION / SUBTRACTION':'එකතු කිරීම හා අඩු කිරීම','MORE EQUATIONS':'තවත් සමීකරණ',COEFFICIENT:'සංගුණකය','VARIABLES BOTH SIDES':'දෙපසම විචල්‍ය ඇති විට','FRACTION EQUATIONS':'භාග සහිත සමීකරණ',PRACTICE:'පුහුණුව','COMMON FACTOR':'පොදු සාධකය','NEGATIVE TERMS':'සෘණ පද','QUADRATIC FACTORISATION':'ද්විතීයික ප්‍රකාශන','NEGATIVE FACTORS':'සෘණ සංඛ්‍යා',CHECK:'පරීක්ෂා කර බලමු',EXPANSION:'විස්තාරණය',IDENTITIES:'සර්වසමතා','BRACKET DENOMINATOR':'වරහනක් සහිත හරය','ADDING FRACTIONS':'භාග එකතු කිරීම','COMMON DENOMINATOR':'පොදු හරය','SIMULTANEOUS INTRO':'සමගාමී සමීකරණ හැඳින්වීම','SIMULTANEOUS ELIMINATION':'ඉවත් කිරීමේ ක්‍රමය','QUADRATIC INTRO':'වර්ග සමීකරණ හැඳින්වීම','COMPLETE SQUARE':'වර්ග පූර්ණ කිරීම','FORMULA PROOF':'වර්ග සමීකරණ සූත්‍රය ඔප්පු කිරීම','FORMULA EXAMPLE':'සූත්‍රය භාවිතයෙන් විසඳීම','QUADRATIC WORD PROBLEM':'වචන ගැටලුවක්','INEQUALITY INTRO':'අසමානතා හැඳින්වීම','INEQUALITY EXAMPLE 1':'උදාහරණය 1','INEQUALITY EXAMPLE 2':'උදාහරණය 2','HCF LCM INTRO':'කුඩාම පොදු ගුණාකාරය','MULTIPLY ALGEBRAIC FRACTIONS':'වීජීය භාග ගුණ කිරීම','RECIPROCAL FRACTION EQUATION':'භාග සමීකරණය','SECTOR 28 CM EXAMPLE':'අරය 28 cm වූ ඛණ්ඩය','COMPOSITE SECTOR QUESTION':'සංයුක්ත රූප ගැටලුව','CYLINDER VOLUME QUESTION':'සිලින්ඩරයේ පරිමාව','MIXED FRACTIONS':'මිශ්‍ර භාග','LCM FRACTIONS':'භාග සඳහා කු.පො.ගු.','COMPLEX FRACTIONS':'සංකීර්ණ භාග','FRACTION WORD PROBLEM 2':'වචන ගැටලුව – ජල ටැංකිය','FRACTION WORD PROBLEM 3':'වචන ගැටලුව – මුදල්','CONE CYLINDER RELATION':'කේතුව හා සිලින්ඩරය','SPHERE CYLINDER RELATION':'ගෝලය හා සිලින්ඩරය','HEMISPHERE VOLUME':'අර්ධගෝලයේ පරිමාව','COMBINED SOLID CONE CYLINDER':'කේතුව හා සිලින්ඩරය මිශ්‍ර කිරීම','SPHERE CYLINDER WORD PROBLEM':'ගෝලය හා සිලින්ඩරය වචන ගැටලුව','CONE SPHERE COMBINATION':'කේතුව හා අර්ධගෝලය','COMBINED SOLID CHECKLIST':'මිශ්‍ර ඝන වස්තු විසඳීම'})[sl.section]||sl.section;$('#slideCounter').textContent=`${String(slideIndex+1).padStart(2,'0')} / ${String(total).padStart(2,'0')}`;$('#slideProgress').style.width=`${((slideIndex+1)/total)*100}%`;$('#slideContent').innerHTML=sl.html;$('#prevSlide').style.display=slideIndex===0?'none':'inline-block';$('#nextSlide').style.display=slideIndex===total-1?'none':'inline-block';$('#prevSlide').disabled=slideIndex===0;$('#nextSlide').textContent=slideIndex===total-2?'පාඩම අවසන් කරන්න →':'ඊළඟ →';localStorage.setItem('td-progress',JSON.stringify({subject:currentSubject,topic:currentTopic.id,index:slideIndex}));}
function renderQA(){const subjectList=$('#qaSubjects');subjectList.innerHTML=subjects.map(s=>`<button class="qa-subject-btn ${s.id===currentQASubject?'active':''}" data-qa-subject="${s.id}">${s.name}</button>`).join('');$$('[data-qa-subject]').forEach(b=>b.addEventListener('click',()=>{currentQASubject=b.dataset.qaSubject;currentQATopic=Object.keys(qaData[currentQASubject]||{})[0]||'';renderQA();}));const topics=Object.keys(qaData[currentQASubject]||{});if(!topics.includes(currentQATopic))currentQATopic=topics[0]||'';$('#qaTitle').textContent=subjects.find(s=>s.id===currentQASubject).name;$('#qaTopics').innerHTML=topics.map(t=>`<button class="qa-topic-btn ${t===currentQATopic?'active':''}" data-qa-topic="${t}">${t}</button>`).join('');$$('[data-qa-topic]').forEach(b=>b.addEventListener('click',()=>{currentQATopic=b.dataset.qaTopic;renderQA();}));const questions=qaData[currentQASubject]?.[currentQATopic]||qaData[currentQASubject]?.['කේන්ද්‍රික ඛණ්ඩ']||[];$('#qaTotal').textContent=`ප්‍රශ්න ${questions.length}ක්`;
 $('#questionList').innerHTML=questions.length?questions.map((q,i)=>`<div class="question-card"><h4>ප්‍රශ්නය ${i+1}. ${q[0]}</h4><button class="answer-toggle">පිළිතුර සහ පැහැදිලි කිරීම බලන්න</button><div class="answer-content">${q[1]}</div></div>`).join(''):'<div class="empty-state">Questions for this topic will be added soon.</div>';
 $$('.answer-toggle').forEach(b=>b.addEventListener('click',()=>{const a=b.nextElementSibling;a.classList.toggle('show');b.textContent=a.classList.contains('show')?'පිළිතුර සඟවන්න':'පිළිතුර සහ පැහැදිලි කිරීම බලන්න';}));}
$('#notesSearch').addEventListener('input',e=>{if(!$('#topicPanel').classList.contains('hidden')){ $('#topicPanel').classList.add('hidden');$('#subjectGrid').classList.remove('hidden');}renderSubjects(e.target.value);});
$('#backToSubjects').addEventListener('click',()=>{$('#topicPanel').classList.add('hidden');$('#subjectGrid').classList.remove('hidden');});
$('#prevSlide').addEventListener('click',()=>{if(slideIndex>0){slideIndex--;renderSlide();}});$('#nextSlide').addEventListener('click',()=>{if(slideIndex<currentSlides.length-1){slideIndex++;renderSlide();}});
$('#exitLesson').addEventListener('click',()=>{setView('notes');openSubject(currentSubject);});
$('#continueBtn').addEventListener('click',()=>{const p=JSON.parse(localStorage.getItem('td-progress')||'null');if(p){openLesson(p.subject,p.topic);slideIndex=Math.min(p.index,currentSlides.length-1);renderSlide();}else{setView('notes');openSubject('algebra');}});
$('#browseBtn').addEventListener('click',()=>setView('notes'));
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>{setView(b.dataset.view);$('#mainNav')?.classList.remove('open');}));
$('#mobileMenu').addEventListener('click',()=>$('.main-nav').classList.toggle('open'));
$('#fontToggle').addEventListener('click',()=>$('#slideContent').classList.toggle('large-text'));
$('#year').textContent=new Date().getFullYear();renderSubjects();renderQA();
